//! Numeric building blocks used by every analysis. Pure functions over `f64`
//! slices; no I/O, no knowledge of flight logs.
//!
//! Every public function has a test against a NumPy/SciPy reference fixture
//! (`tests/reference/*.json`, generated by `tools/reference/make_fixtures.py`)
//! and/or an analytic property test.

pub mod deconv;
pub mod fft;
pub mod resample;
pub mod smooth;
pub mod spectrum;
pub mod window;

pub use fft::{Complex, Fft};
pub use window::Window;

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum DspError {
    #[error("input too short: need at least {need} samples, got {got}")]
    TooShort { need: usize, got: usize },
    #[error("invalid parameter: {0}")]
    InvalidParam(String),
}

/// Smallest `n >= target` whose prime factors are all in {2, 3, 5}.
/// rustfft handles any length; "5-smooth" lengths are simply the fastest.
pub fn next_smooth(target: usize) -> usize {
    let mut n = target.max(1);
    loop {
        let mut m = n;
        for p in [2usize, 3, 5] {
            while m.is_multiple_of(p) {
                m /= p;
            }
        }
        if m == 1 {
            return n;
        }
        n += 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn smooth_lengths() {
        assert_eq!(next_smooth(1), 1);
        assert_eq!(next_smooth(7), 8);
        assert_eq!(next_smooth(1000), 1000);
        assert_eq!(next_smooth(1001), 1024);
        assert_eq!(next_smooth(4001), 4050);
    }
}
